@dataclass
class Violation:
    rule_id: str
    rule_text: str
    section: str
    file_path: str
    why: str
    mitigation: str


def list_changed_files(base_ref: str) -> list[Path]:
    merge_base = subprocess.check_output(
        ["git", "merge-base", base_ref, "HEAD"], text=True
    ).strip()
    out = subprocess.check_output(
        ["git", "diff", "--name-only", f"{merge_base}..HEAD"], text=True
    )
    return [Path(line.strip()) for line in out.splitlines() if line.strip()]


def read_text(file_path: Path) -> str:
    try:
        return file_path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return file_path.read_text(encoding="latin-1", errors="ignore")


def check_sql_snake_case_identifiers(file_path: Path, text: str) -> list[tuple[str, str]]:
    findings: list[tuple[str, str]] = []
    if file_path.suffix.lower() != ".sql":
        return findings

    for token in re.findall(r"\b[A-Za-z][A-Za-z0-9_]*\b", text):
        if token.lower() in {
            "select", "from", "where", "join", "group", "order", "by", "as", "and", "or", "on",
            "insert", "update", "delete", "create", "table", "view", "into", "values", "case",
            "when", "then", "else", "end"
        }:
            continue
        if token != token.lower():
            findings.append(
                (
                    f"Identifier '{token}' is not snake_case.",
                    "SQL identifiers must use snake_case.",
                )
            )
            if len(findings) >= 20:
                break
    return findings


def check_sql_table_layer_domain_object(file_path: Path, text: str) -> list[tuple[str, str]]:
    findings: list[tuple[str, str]] = []
    if file_path.suffix.lower() != ".sql":
        return findings

    pattern = re.compile(
        r'\b(?:create|alter)\s+table\s+(?:if\s+not\s+exists\s+)?([A-Za-z0-9_\."\[\]]+)',
        re.IGNORECASE,
    )
    allowed = re.compile(r"^(bronze|silver|gold)_[a-z0-9]+_[a-z0-9_]+$")
    for match in pattern.finditer(text):
        raw = match.group(1)
        table_name = raw.split(".")[-1].strip('"[]').lower()
        if not allowed.match(table_name):
            findings.append(
                (
                    f"Table '{raw}' does not follow [layer]_[domain]_[object].",
                    "Expected layer prefix and domain/object naming standard.",
                )
            )
    return findings


def check_sql_fact_dim_prefix(file_path: Path, text: str) -> list[tuple[str, str]]:
    findings: list[tuple[str, str]] = []
    if file_path.suffix.lower() != ".sql":
        return findings

    pattern = re.compile(
        r'\bcreate\s+table\s+(?:if\s+not\s+exists\s+)?([A-Za-z0-9_\."\[\]]+)',
        re.IGNORECASE,
    )
    for match in pattern.finditer(text):
        raw = match.group(1)
        table_name = raw.split(".")[-1].strip('"[]').lower()
        if "fact" in table_name and not table_name.startswith("fact_"):
            findings.append(
                (
                    f"Fact-like table '{raw}' is missing fact_ prefix.",
                    "Fact tables must be prefixed with fact_.",
                )
            )
        if "dim" in table_name and not table_name.startswith("dim_"):
            findings.append(
                (
                    f"Dimension-like table '{raw}' is missing dim_ prefix.",
                    "Dimension tables must be prefixed with dim_.",
                )
            )
    return findings


def check_utc_timestamp_usage(file_path: Path, text: str) -> list[tuple[str, str]]:
    findings: list[tuple[str, str]] = []
    suffix = file_path.suffix.lower()

    if suffix == ".py":
        if "datetime.now(" in text and "timezone.utc" not in text:
            findings.append(
                (
                    "datetime.now(...) detected without timezone.utc.",
                    "Use timezone-aware UTC timestamps in Python.",
                )
            )
    elif suffix == ".sql":
        local_time_tokens = ["GETDATE(", "CURRENT_TIMESTAMP", "SYSDATETIME("]
        for token in local_time_tokens:
            if token in text.upper():
                findings.append(
                    (
                        f"Potential local time function detected: {token}",
                        "Use UTC-compatible timestamp expressions.",
                    )
                )
    return findings


def check_retry_logic_presence(file_path: Path, text: str) -> list[tuple[str, str]]:
    findings: list[tuple[str, str]] = []
    if file_path.name.endswith((".yml", ".yaml")) and ".github/workflows/" in file_path.as_posix():
        lowered = text.lower()
        if "retry" not in lowered:
            findings.append(
                (
                    "Workflow does not mention retry handling.",
                    "Standards require 3 retry attempts with exponential backoff for scheduled refresh logic.",
                )
            )
    return findings


CHECKERS = {
    "sql_snake_case_identifiers": check_sql_snake_case_identifiers,
    "sql_table_layer_domain_object": check_sql_table_layer_domain_object,
    "sql_fact_dim_prefix": check_sql_fact_dim_prefix,
    "utc_timestamp_usage": check_utc_timestamp_usage,
    "retry_logic_presence": check_retry_logic_presence,
}


def validate(base_ref: str, include_manual: bool) -> tuple[list[Violation], list[dict]]:
    changed_files = [p for p in list_changed_files(base_ref) if p.exists()]
    violations: list[Violation] = []
    manual_rules: list[dict] = []

    text_cache: dict[Path, str] = {}
    for file_path in changed_files:
        if file_path.is_file():
            text_cache[file_path] = read_text(file_path)

    for rule in RULES:
        checker_name = rule.get("checker")
        if not checker_name:
            if include_manual:
                manual_rules.append(rule)
            continue

        checker = CHECKERS.get(checker_name)
        if checker is None:
            continue

        for file_path, text in text_cache.items():
            for why, evidence in checker(file_path, text):
                violations.append(
                    Violation(
                        rule_id=str(rule["id"]),
                        rule_text=str(rule["text"]),
                        section=str(rule["section"]),
                        file_path=file_path.as_posix(),
                        why=f"{why} {evidence}",
                        mitigation=str(rule["mitigation"]),
                    )
                )

    return violations, manual_rules


def to_markdown(
    violations: list[Violation],
    manual_rules: list[dict],
    source_url: str,
    last_synced_utc: str,
    page_title: str,
) -> str:
    lines = [
        "# Development Standards Validation Report",
        "",
        f"- Source: {source_url}",
        f"- Last synced: {last_synced_utc}",
        f"- Rules catalog title: {page_title}",
        "",
    ]

    if violations:
        lines.extend(["## Violations", ""])
        for item in violations:
            lines.extend(
                [
                    f"### {item.rule_id}",
                    f"- Section: {item.section}",
                    f"- File: {item.file_path}",
                    f"- Rule failed: {item.rule_text}",
                    f"- Why: {item.why}",
                    f"- Mitigation: {item.mitigation}",
                    "",
                ]
            )
    else:
        lines.extend(["## Violations", "", "No automated violations found.", ""])

    lines.extend(["## Manual Review Rules", ""])
    if manual_rules:
        for rule in manual_rules:
            lines.extend(
                [
                    f"### {rule['id']}",
                    f"- Section: {rule['section']}",
                    f"- Rule: {rule['text']}",
                    "- Why manual: No deterministic checker is mapped yet.",
                    f"- Mitigation: {rule['mitigation']}",
                    "",
                ]
            )
    else:
        lines.append("No manual rules recorded.")

    return "\n".join(lines).strip() + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate PR changes against development standards")
    parser.add_argument("--base-ref", default="origin/main", help="Base ref for PR diff (default: origin/main)")
    parser.add_argument(
        "--report-path",
        default="development-standards-validation.md",
        help="Where to write Markdown validation output",
    )
    parser.add_argument(
        "--include-manual",
        action="store_true",
        help="Include manual-review rule list in the report",
    )
    parser.add_argument(
        "--json-path",
        default="development-standards-validation.json",
        help="Where to write machine-readable violations",
    )
    args = parser.parse_args()

    violations, manual_rules = validate(args.base_ref, include_manual=args.include_manual)

    markdown_report = to_markdown(
        violations,
        manual_rules,
        source_url=SOURCE_URL,
        last_synced_utc=LAST_SYNCED_UTC,
        page_title=PAGE_TITLE,
    )
    Path(args.report_path).write_text(markdown_report, encoding="utf-8")

    json_payload = {
        "source": SOURCE_URL,
        "last_synced_utc": LAST_SYNCED_UTC,
        "rule_count": len(RULES),
        "violation_count": len(violations),
        "violations": [v.__dict__ for v in violations],
    }
    Path(args.json_path).write_text(json.dumps(json_payload, indent=2), encoding="utf-8")

    if violations:
        print(f"Validation failed: {len(violations)} violation(s).")
        print(f"Markdown report: {args.report_path}")
        print(f"JSON report: {args.json_path}")
        return 1

    print("Validation passed: no automated violations.")
    print(f"Markdown report: {args.report_path}")
    print(f"JSON report: {args.json_path}")
    return 0

